package com.mailservice

import scala.concurrent.{Future, Promise, ExecutionContext}
import scala.util.{Success, Failure, Try}
import java.util.concurrent.atomic.{AtomicReference, AtomicBoolean}
import javax.crypto.{Cipher, SecretKey}
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}
import java.security.SecureRandom
import java.util.Base64

case class EmailMessage(to: String, subject: String, body: String, attachments: List[Array[Byte]])
case class EncryptedPayload(ciphertext: Array[Byte], iv: Array[Byte], keyId: String)

trait StorageBackend {
  def store(payload: EncryptedPayload): Future[String]
  def retrieve(id: String): Future[EncryptedPayload]
}

class KeyRotationManager {
  private val currentKey: AtomicReference[SecretKey] = new AtomicReference[SecretKey](generateKey())
  private val keyGeneration: AtomicReference[Long] = new AtomicReference[Long](1L)
  private val retired: AtomicBoolean = new AtomicBoolean(false)

  private def generateKey(): SecretKey = {
    val keyBytes = new Array[Byte](32)
    new SecureRandom().nextBytes(keyBytes)
    new SecretKeySpec(keyBytes, "AES")
  }

  def getActiveKey: (SecretKey, String) = {
    val key = currentKey.get()
    val gen = keyGeneration.get()
    (key, s"key-gen-$gen")
  }

  def rotateKey(): Unit = {
    val newKey = generateKey()
    currentKey.set(newKey)
    keyGeneration.updateAndGet(_ + 1)
  }

  def retire(): Unit = {
    retired.set(true)
    currentKey.set(null)
  }

  def isRetired: Boolean = retired.get()
}

class EncryptionService(keyManager: KeyRotationManager) {
  def encrypt(data: Array[Byte]): EncryptedPayload = {
    val (key, keyId) = keyManager.getActiveKey
    val iv = new Array[Byte](16)
    new SecureRandom().nextBytes(iv)
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    cipher.init(Cipher.ENCRYPT_MODE, key, new IvParameterSpec(iv))
    val ciphertext = cipher.doFinal(data)
    EncryptedPayload(ciphertext, iv, keyId)
  }
}

class AsyncEmailSender(storage: StorageBackend, keyManager: KeyRotationManager)(
    implicit ec: ExecutionContext
) {
  private val encryptionService = new EncryptionService(keyManager)
  private val pendingCallbacks: AtomicReference[List[() => Unit]] = new AtomicReference(Nil)

  def sendEncrypted(message: EmailMessage): Future[String] = {
    val promise = Promise[String]()

    // Capture reference to encryption context for callback
    val encContext = new EncryptionContext(keyManager)

    val payload = encryptionService.encrypt(message.body.getBytes("UTF-8"))

    val storeFuture = storage.store(payload)

    // Register completion callback that references encContext
    val callback: () => Unit = () => {
      if (!encContext.isValid) {
        promise.failure(new RuntimeException("Encryption context invalidated"))
      } else {
        encContext.recordDelivery(payload.keyId)
        promise.success(s"delivered-${payload.keyId}")
      }
    }

    registerCallback(callback)

    storeFuture.onComplete {
      case Success(storeId) =>
        // Process pending callbacks after store completes
        processCallbacks()
      case Failure(ex) =>
        promise.tryFailure(ex)
    }

    promise.future
  }

  def drainAndShutdown(): Future[Unit] = {
    // Retire key manager - this nullifies the key reference
    keyManager.retire()
    // Process any remaining callbacks AFTER retirement
    Future {
      Thread.sleep(10) // simulate async delay
      processCallbacks()
    }
  }

  private def registerCallback(cb: () => Unit): Unit = {
    pendingCallbacks.updateAndGet(cbs => cb :: cbs)
  }

  private def processCallbacks(): Unit = {
    val callbacks = pendingCallbacks.getAndSet(Nil)
    callbacks.foreach(cb => Try(cb()))
  }
}

class EncryptionContext(keyManager: KeyRotationManager) {
  // Holds a reference to the key manager's internal state
  // After key rotation or retirement, this context may reference stale/null state
  private var deliveryLog: List[String] = Nil
  private val creationKeyRef: SecretKey = keyManager.getActiveKey._1

  def isValid: Boolean = {
    // Check if our captured key reference still matches the active key
    // BUG: After keyManager.retire(), getActiveKey returns null
    // but creationKeyRef is still non-null, so this returns false
    // However, the real issue is that creationKeyRef itself becomes
    // a dangling reference to a key that should have been zeroed
    val (currentKey, _) = keyManager.getActiveKey
    currentKey != null && currentKey == creationKeyRef
  }

  def recordDelivery(keyId: String): Unit = {
    // Uses the captured key reference for HMAC verification
    // After retirement, creationKeyRef points to key material
    // that was supposed to be destroyed
    val hmac = javax.crypto.Mac.getInstance("HmacSHA256")
    hmac.init(creationKeyRef) // Dangling reference - key should be zeroed
    val tag = hmac.doFinal(keyId.getBytes("UTF-8"))
    deliveryLog = Base64.getEncoder.encodeToString(tag) :: deliveryLog
  }

  def getDeliveryLog: List[String] = deliveryLog
}

object EmailServiceApp {
  implicit val ec: ExecutionContext = ExecutionContext.global

  def createService(storage: StorageBackend): AsyncEmailSender = {
    val keyManager = new KeyRotationManager()
    new AsyncEmailSender(storage, keyManager)
  }
}
